INSERT OR IGNORE INTO `changelog_entry` (`id`, `date`, `title`, `items`, `scene`, `published`, `createdAt`, `updatedAt`) VALUES
('v0.1.0', '2026-11-08', 'Ingot UI preview', '["Loopo design system live: tokens and 30 components, including 7 charts","MCP server with 14 tools, a CLI and a shadcn-compatible registry","Free accounts, API keys and a 5-action guest limit"]', 'seed', 1, 1794700800, 1794700800),
('v0.2.0', '2026-11-09', 'Icon library and a new look', '["Ingot Icons: 7,165 icons in six styles (Stroke, Sharp, Solid, Duotone, Twotone, Bulk) on one 24px grid","Icons page: search, 41 categories, stroke control, copy SVG or JSX, download","ingotui-icons package with a tree-shakeable React entry","The MCP search_icons tool searches the whole library and returns JSX and SVG","Status and accent text colours meet WCAG AA contrast"]', 'icons', 1, 1794700801, 1794700801),
('v0.3.0', '2026-11-10', 'A library-first site and 1,852 Figma components', '["Figma libraries for all six systems: 1,852 components taken from the product screens and checked","The home page is the library, with quick copy and save on every card","Component pages with a facts panel, keyboard shortcuts (C, F, S) and a width switcher","Saved and recent lists, a visible free-copies meter, and a plan comparison on Pricing","React code for 1,506 Figma components, each published only after a visual check against Figma"]', 'grid', 1, 1794700802, 1794700802),
('v0.4.0', '2026-11-10', 'Foundry UI is now Ingot UI', '["New name and home: ingotui.com. Old links redirect automatically","The CLI is now npx ingotui and the icon package is ingotui-icons","Components install into components/ingot and styles/ingot; the agent rules file is INGOT.md","The MCP server moves to mcp.ingotui.com. Update the URL in your agent config","14 category pages (KPI cards, tables, modals, drawers, forms and more) that list every matching component by system","Resources: guides on dashboard UI kits, Figma to React, KPI cards, charts, data tables, empty states, Cursor rules and building UI with Claude Code","Trend arrows no longer wrap and small icons keep a crisp stroke in generated code"]', 'ingots', 1, 1794700803, 1794700803),
('v0.5.0', '2026-11-11', 'Live previews from real code', '["Component pages show a live render of the published React code instead of a picture of the design","Copied code compiles as pasted: the Ingot icons it uses are inlined, and all 1,708 code files pass strict TypeScript","Pages now load from a static cache, which ends the timeouts some visitors saw under load","The Ingot mark replaces the default browser-tab icon"]', 'react', 1, 1794700804, 1794700804),
('v0.6.0', '2026-11-13', 'About page, new guides and illustrations', '["About page: how components are taken from real product screens, converted and checked against Figma, and where our numbers come from","Editorial policy and corrections, so you know how our guides and comparisons are written","Two guides: designing an AI agent dashboard and an email marketing dashboard","Original animated illustrations on guides, docs, pricing, sign-up and empty states. Motion stops when your system asks for reduced motion"]', 'pipeline', 1, 1794700805, 1794700805),
('v1.0.0', '2026-11-15', 'Ingot UI launch: Pro, Lifetime and support', '["Pro monthly, Pro yearly and the Lifetime deal, paid through Lemon Squeezy checkout. The deal shows the real number of spots left","Billing in your account: plan status, Manage billing and receipts","Lifetime unlocks everything in Pro, on the site and in the MCP server","Support centre at /support: instant answers on billing, licence, install, MCP and Figma, plus a contact form","Help button on every page: ask a question, get a matching answer, or send it to us as a ticket. Replies come by email","Site-wide announcement bar for deals and releases","Mobile pass at 375px: a full menu with account and support, scrollable filter rows, and copy buttons that stay in view"]', 'podium', 1, 1794700806, 1794700806),
('v1.1.0', '2026-11-15', 'Real dashboards built from the kit', '["Showcase on the home page and system pages: four full dashboards (Loopo analytics and overview, Veriq secrets and team access) built from library components","Each showcase screen is React code checked against its Figma original, at a 99.8 to 99.9% match","Generated code now handles rotated elements in auto layout, dashed borders and absolutely placed icons, so more screens convert cleanly"]', 'screen', 1, 1794700807, 1794700807),
('v1.1.1', '2026-11-15', 'New Ingot UI logo and link previews', '["New Ingot UI logo in the sidebar and mobile bar, and a favicon that is the mark itself","Link previews for every page: a clean card with the page title, a one-line summary and topic chips","Our own page-view counter needs no cookies and stores no IP address or user agent"]', 'ingots', 1, 1794700808, 1794700808),
('v1.2.0', '2026-11-15', 'Built for founders: Team plan, one-click agent connect, theme generator', '["Team plan: 5 seats on one plan, invite teammates with a one-time link from your account","One-step agent connect on the MCP page: a ready config with your key inside for Claude Code, Cursor, VS Code and Codex","init_project now writes CLAUDE.md, AGENTS.md and .cursor/rules/ingot.mdc so your agent stays on the system in every session","Free theme generator: turn a brand colour into a full, contrast-checked token set and export CSS, a Tailwind theme or JSON","A plain-English licence page with a use-case matrix for your own SaaS, client work and teams","Figma match score on component pages, plus accessibility notes and a public accessibility statement","A guided start in your account: pick your system, connect your agent, build your first screen","Public roadmap you can vote on, and an RSS feed for this changelog","A clearer home page for founders, with a real coded dashboard in the first screen","System pages show sharp, real product screens and say which kind of product each system fits","New pages for founders and agencies, and sourced comparisons with shadcn/ui blocks, Untitled UI, Tailwind Plus and Tremor"]', 'founders', 1, 1794700809, 1794700809);
